-- AI Piutang Vouching - Supabase PostgreSQL schema
-- Version: 1.0
create extension if not exists pgcrypto;
create table if not exists public.import_batches (id bigint generated by default as identity primary key,file_name varchar(255) not null,period date,uploaded_by varchar(100),uploaded_at timestamptz not null default now(),total_records integer not null default 0 check (total_records >= 0),status varchar(30) not null default 'UPLOADED');
create table if not exists public.documents (id bigint generated by default as identity primary key,file_name varchar(255) not null,file_type varchar(20) not null,document_type varchar(20) not null check (document_type in ('SPJ','BILLING')),file_hash varchar(128) not null,storage_path varchar(1024) not null,uploaded_by varchar(100),uploaded_at timestamptz not null default now());
create table if not exists public.sap_billing (id bigint generated by default as identity primary key,import_batch_id bigint not null references public.import_batches(id) on delete restrict,customer varchar(255),customer_account_name varchar(255),billing_document varchar(100) not null,doc_date date not null,nominal numeric(20,2) not null,created_at timestamptz not null default now(),constraint uq_sap_billing_batch_document unique (import_batch_id,billing_document));
create table if not exists public.physical_billing (id bigint generated by default as identity primary key,document_id bigint not null unique references public.documents(id) on delete cascade,billing_document_raw text,billing_document varchar(100),no_spj_raw text,no_spj varchar(100),doc_date date,nominal numeric(20,2),partial_payment_raw text,partial_payment numeric(20,2) check (partial_payment is null or partial_payment >= 0),ocr_confidence numeric(5,4) check (ocr_confidence is null or (ocr_confidence >= 0 and ocr_confidence <= 1)),created_at timestamptz not null default now());
create table if not exists public.spj (id bigint generated by default as identity primary key,document_id bigint not null unique references public.documents(id) on delete cascade,no_spj_raw text,no_spj varchar(100),partial_payment_raw text,partial_payment numeric(20,2) check (partial_payment is null or partial_payment >= 0),ocr_confidence numeric(5,4) check (ocr_confidence is null or (ocr_confidence >= 0 and ocr_confidence <= 1)),created_at timestamptz not null default now());
create table if not exists public.billing_reconciliation (id bigint generated by default as identity primary key,sap_billing_id bigint not null unique references public.sap_billing(id) on delete cascade,physical_billing_id bigint unique references public.physical_billing(id) on delete set null,billing_match boolean not null,date_match boolean not null,nominal_match boolean not null,nominal_difference numeric(20,2) not null,status varchar(20) not null check (status in ('MATCH','REVIEW','EXCEPTION','NOT_FOUND')),exception_code varchar(50),remarks text,created_at timestamptz not null default now());
create table if not exists public.vouching_result (id bigint generated by default as identity primary key,billing_id bigint not null unique references public.physical_billing(id) on delete cascade,spj_id bigint references public.spj(id) on delete set null,no_spj_billing varchar(100),no_spj_document varchar(100),spj_match boolean not null,status varchar(20) not null check (status in ('PASS','REVIEW','EXCEPTION')),rule_code varchar(50),remarks text,reviewer_id varchar(100),reviewed_at timestamptz);
create table if not exists public.audit_trail (id bigint generated by default as identity primary key,entity_type varchar(50) not null,entity_id bigint,action varchar(50) not null,status_from varchar(30),status_to varchar(30),actor varchar(100),remarks text,metadata_json jsonb,created_at timestamptz not null default now());
create table if not exists public.document_extractions (id bigint generated by default as identity primary key,document_id bigint not null references public.documents(id) on delete cascade,field_name varchar(100) not null,raw_value text,normalized_value text,confidence numeric(5,4) check (confidence is null or (confidence >= 0 and confidence <= 1)),page_number integer,bbox jsonb,engine varchar(100),created_at timestamptz not null default now());
create table if not exists public.document_marks (id bigint generated by default as identity primary key,document_id bigint not null references public.documents(id) on delete cascade,mark_type varchar(50) not null check (mark_type in ('SIGNATURE_RECIPIENT','SIGNATURE_DRIVER','SIGNATURE_SECURITY','SIGNATURE_BM','STAMP_RECIPIENT','HANDWRITING','OTHER')),detected boolean not null,confidence numeric(5,4) check (confidence is null or (confidence >= 0 and confidence <= 1)),bbox jsonb,crop_storage_path text,engine varchar(100),review_status varchar(20) not null default 'UNREVIEWED' check (review_status in ('UNREVIEWED','CONFIRMED','REJECTED','REVIEW')),created_at timestamptz not null default now());
create table if not exists public.handwriting_adjustments (id bigint generated by default as identity primary key,document_id bigint not null references public.documents(id) on delete cascade,raw_text text not null,amount numeric(20,2),classification varchar(30) not null default 'UNKNOWN' check (classification in ('PAYMENT','DISCOUNT','DEDUCTION','CORRECTION','REMAINING','FINAL_AMOUNT','UNKNOWN')),confidence numeric(5,4) check (confidence is null or (confidence >= 0 and confidence <= 1)),bbox jsonb,crop_storage_path text,source_page integer,auditor_status varchar(20) not null default 'REVIEW' check (auditor_status in ('REVIEW','ACCEPTED','REJECTED')),auditor_note text,created_at timestamptz not null default now());
create index if not exists ix_sap_billing_billing_document on public.sap_billing(billing_document);
create index if not exists ix_physical_billing_billing_document on public.physical_billing(billing_document);
create index if not exists ix_physical_billing_no_spj on public.physical_billing(no_spj);
create index if not exists ix_spj_no_spj on public.spj(no_spj);
create index if not exists ix_billing_reconciliation_status on public.billing_reconciliation(status);
create index if not exists ix_vouching_result_status on public.vouching_result(status);
create index if not exists ix_audit_trail_entity on public.audit_trail(entity_type,entity_id);
create index if not exists ix_audit_trail_created_at on public.audit_trail(created_at);
create index if not exists ix_document_extractions_document on public.document_extractions(document_id);
create index if not exists ix_document_marks_document on public.document_marks(document_id);
create index if not exists ix_handwriting_adjustments_document on public.handwriting_adjustments(document_id);
insert into storage.buckets (id,name,public) values ('vouching-evidence','vouching-evidence',false) on conflict (id) do update set public=false;
alter table public.import_batches enable row level security;
alter table public.documents enable row level security;
alter table public.sap_billing enable row level security;
alter table public.physical_billing enable row level security;
alter table public.spj enable row level security;
alter table public.billing_reconciliation enable row level security;
alter table public.vouching_result enable row level security;
alter table public.audit_trail enable row level security;
alter table public.document_extractions enable row level security;
alter table public.document_marks enable row level security;
alter table public.handwriting_adjustments enable row level security;
